import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { easternBlokQuotes, leaderQuotes, quoteParts } from "./data/press-timeline.js";

// The site may only show press Doug has approved, quoted word for word.
// press/press.json (generated by press/merge-press.cjs) is the source of truth.
const pressFile = JSON.parse(readFileSync(new URL("../../press/press.json", import.meta.url), "utf8"));
const entries = Array.isArray(pressFile) ? pressFile : pressFile.entries;
const byId = new Map(entries.map((entry) => [entry.id, entry]));
const all = [...easternBlokQuotes, ...leaderQuotes];

// Curly and straight apostrophes are treated as the same character.
const normalize = (s) => s.replace(/[’‘]/g, "'").trim();

for (const quote of all) {
	test(`${quote.id} is approved in press/press.json`, () => {
		const entry = byId.get(quote.id);
		assert.ok(entry, `no entry with id ${quote.id}`);
		assert.equal(entry.approved, true);
	});

	test(`${quote.id} quotes the source word for word`, () => {
		const entry = byId.get(quote.id);
		const excerpt = normalize(quote.text.replace(/^…|…$/g, ""));
		const sources = (entry?.pullQuotes ?? []).map((q) => normalize(typeof q === "string" ? q : q.text));
		assert.ok(
			sources.some((source) => source.includes(excerpt)),
			`"${excerpt}" is not in any pull quote of ${quote.id}`,
		);
	});

	test(`${quote.id} links to the same page as the press index`, () => {
		assert.equal(quote.url, byId.get(quote.id)?.url ?? null);
	});

	test(`${quote.id} highlight appears in the quote`, () => {
		if (quote.highlight) assert.ok(quote.text.includes(quote.highlight));
	});
}

test("quoteParts splits out the highlighted name", () => {
	assert.deepEqual(quoteParts({ text: "a Doug b", highlight: "Doug" }), [
		{ text: "a ", highlight: false },
		{ text: "Doug", highlight: true },
		{ text: " b", highlight: false },
	]);
	assert.deepEqual(quoteParts({ text: "no name" }), [{ text: "no name", highlight: false }]);
});
